def model(p,cols_extra=None):
    return p[0]+p[1]*t**2+p[2]*np.sin(p[3]*t)*np.sqrt(v)
best=None
for w in np.linspace(0.1,4,40):
    r=least_squares(lambda p: model(p)-dv_dt, [8,-0.2,-0.4,w])
    if best is None or r.cost<best.cost: best=r
